import './City.css';
import Cities from '../../../data/city.json';

const City = () => {
	return (
		<div className="city">
			{Cities.map((city, index) => {
				return (
					<div key={index}>
						<div className="city-Item">
							<img src={city.image} alt="" className="city-Img" />
							<div className="city-Titles">
								<h1> {city.name} </h1>
								<h2>{city.subText}</h2>
							</div>
						</div>
					</div>
				);
			})}
		</div>
	);
};

export default City;
